// TensorFlow.js model loader and predictor for exoplanet habitability
// Note: The provided model expects 52 features (input shape [null, 52]).
// By default, we will place the 6 UI inputs in indices 0-5 and zero-fill the rest.
// For correct predictions, provide a feature mapping and normalization file at `/model/feature_map.json`.

import * as tf from '@tensorflow/tfjs';

const PUBLIC_URL = process.env.PUBLIC_URL || '';
const DEFAULT_MODEL_URL = `${PUBLIC_URL}/model/model.json`;
const MODEL_URL = process.env.REACT_APP_TFJS_MODEL_URL || DEFAULT_MODEL_URL;

let modelPromise = null;
let featureConfigPromise = null;

// Load optional feature configuration mapping and normalization
async function loadFeatureConfig() {
  if (!featureConfigPromise) {
    const featureMapUrl = `${PUBLIC_URL}/model/feature_map.json`;
    featureConfigPromise = fetch(featureMapUrl, { cache: 'no-store' })
      .then(async (r) => {
        if (!r.ok) return null;
        try {
          return await r.json();
        } catch (_e) {
          return null;
        }
      })
      .catch(() => null);
  }
  return featureConfigPromise;
}

export async function loadModel() {
  if (!modelPromise) {
    modelPromise = tf.loadLayersModel(MODEL_URL);
  }
  return modelPromise;
}

function applyNormalization(value, norm) {
  if (!norm) return value;
  const { type, mean, std, min, max } = norm;
  if (type === 'standard' && typeof mean === 'number' && typeof std === 'number' && std !== 0) {
    return (value - mean) / std;
  }
  if (type === 'minmax' && typeof min === 'number' && typeof max === 'number' && max !== min) {
    return (value - min) / (max - min);
  }
  return value;
}

// Build an input vector of the model's expected size. If a feature map is present, use it; otherwise place
// UI fields in indices 0-5 in this order: planetRadius, orbitalPeriod, stellarMass,
// equilibriumTemp, eccentricity, stellarRadius
async function buildInputVector(raw, inputSize) {
  const featureConfig = await loadFeatureConfig();
  const size = typeof inputSize === 'number' && inputSize > 0 ? inputSize : 52;
  const input = new Array(size).fill(0);

  if (featureConfig && Array.isArray(featureConfig.features)) {
    // feature_map.json format example:
    // {
    //   "features": [
    //     { "name": "planetRadius", "index": 3, "norm": {"type":"standard","mean":0.98,"std":0.2} },
    //     { "name": "orbitalPeriod", "index": 10, "norm": {"type":"minmax","min":0,"max":10000} },
    //     ... 52 entries total ...
    //   ],
    //   "classLabels": ["non_habitable", "marginal", "prime"]
    // }
    featureConfig.features.forEach((f) => {
      const value = raw[f.name];
      if (typeof f.index === 'number' && f.index >= 0 && f.index < size && typeof value === 'number') {
        input[f.index] = applyNormalization(value, f.norm);
      }
    });
    return { vector: input, classLabels: featureConfig.classLabels || null };
  }

  // Fallback simple placement without normalization
  const ordered = [
    raw.planetRadius,
    raw.orbitalPeriod,
    raw.stellarMass,
    raw.equilibriumTemp,
    raw.eccentricity,
    raw.stellarRadius,
  ];
  for (let i = 0; i < ordered.length && i < size; i += 1) {
    const v = typeof ordered[i] === 'number' ? ordered[i] : 0;
    input[i] = v;
  }
  return { vector: input, classLabels: null };
}

// Run prediction and return softmax probabilities and class index
export async function predictWithModel(planetData) {
  const model = await loadModel();
  const inferredInputSize = (model && model.inputs && model.inputs[0] && Array.isArray(model.inputs[0].shape))
    ? model.inputs[0].shape[1]
    : 52;
  const { vector, classLabels } = await buildInputVector(planetData, inferredInputSize);

  const size = Array.isArray(vector) ? vector.length : 52;
  const tensor = tf.tensor2d([vector], [1, size]);
  const logits = model.predict(tensor);
  const probs = await logits.data();
  tf.dispose([tensor, logits]);

  let maxIdx = 0;
  for (let i = 1; i < probs.length; i += 1) {
    if (probs[i] > probs[maxIdx]) maxIdx = i;
  }

  return {
    probabilities: Array.from(probs),
    predictedClassIndex: maxIdx,
    classLabels,
  };
}

// Predict directly from a numeric feature vector matching the model's input size
export async function predictFromVector(featureVector) {
  const model = await loadModel();
  const inferredInputSize = (model && model.inputs && model.inputs[0] && Array.isArray(model.inputs[0].shape))
    ? model.inputs[0].shape[1]
    : 52;

  if (!Array.isArray(featureVector) || featureVector.length !== inferredInputSize) {
    throw new Error(`Expected feature vector of length ${inferredInputSize}, got ${Array.isArray(featureVector) ? featureVector.length : 'invalid'}`);
  }

  const tensor = tf.tensor2d([featureVector], [1, inferredInputSize]);
  const logits = model.predict(tensor);
  const probs = await logits.data();
  tf.dispose([tensor, logits]);

  let maxIdx = 0;
  for (let i = 1; i < probs.length; i += 1) {
    if (probs[i] > probs[maxIdx]) maxIdx = i;
  }

  const classLabels = null; // optional via feature_map in predictWithModel path
  return {
    probabilities: Array.from(probs),
    predictedClassIndex: maxIdx,
    classLabels,
  };
}

// Translate TFJS outputs to the app's result format
export async function predictHabitabilityTFJS(planetData) {
  const { probabilities, predictedClassIndex, classLabels } = await predictWithModel(planetData);

  // Default class mapping if not provided: 0=Non-Habitable, 1=Partially/Marginal, 2=Prime
  const labels = classLabels && classLabels.length === probabilities.length
    ? classLabels
    : ['non_habitable', 'marginal', 'prime'];

  const confidence = Math.round(probabilities[predictedClassIndex] * 1000) / 10; // 0-100%

  // Derive a 0-100 habitability score from weighted probabilities;
  // give more weight to the highest class (assume index 2 is best by default)
  const score = Math.round((probabilities[2] * 100) * 10) / 10;

  let classification = 'Non-Habitable';
  if (labels[predictedClassIndex] === 'prime' || predictedClassIndex === 2) classification = 'Prime Habitable';
  else if (labels[predictedClassIndex] === 'marginal' || predictedClassIndex === 1) classification = 'Marginal Habitable';

  return {
    habitabilityScore: score,
    confidence,
    classification,
    raw: {
      classLabels: labels,
      probabilities,
      predictedClassIndex,
    },
  };
}

// Translate TFJS outputs to app format for direct vector input
export async function predictHabitabilityTFJSFromVector(featureVector) {
  const { probabilities, predictedClassIndex } = await predictFromVector(featureVector);
  const labels = ['non_habitable', 'marginal', 'prime'];
  const confidence = Math.round(probabilities[predictedClassIndex] * 1000) / 10;
  const score = Math.round((probabilities[2] * 100) * 10) / 10;
  let classification = 'Non-Habitable';
  if (predictedClassIndex === 2) classification = 'Prime Habitable';
  else if (predictedClassIndex === 1) classification = 'Marginal Habitable';

  return {
    habitabilityScore: score,
    confidence,
    classification,
    raw: {
      classLabels: labels,
      probabilities,
      predictedClassIndex,
    },
  };
}


